const Q=(id,prompt,options,answer,why,concept)=>({id:'bonding.'+id,prompt,options,answer,why,concept:'bonding.'+concept});
const N=(id,prompt,answer,why,concept,unit)=>({...Q(id,prompt,[],answer,why,concept),type:'number',tolerance:0,unit});
const C=(title,text,scene)=>({title,text,scene:'carbon:'+scene});
export const carbonLessons=[
{id:'science.chemistry.bonding.diamond',title:'Diamond: a rigid carbon network',short:'Four bonds, a rigid structure',refs:['2.3.1'],minutes:20,widget:'diamond-lab',prerequisites:['science.chemistry.bonding.giant-covalent'],big:'Each carbon in diamond forms four covalent bonds in a giant three-dimensional network. Structure explains hardness, high melting point and electrical insulation.',learn:[
C('Same element, different arrangement.','Diamond and graphite are allotropes: different structural forms of the element carbon. Their carbon atoms have the same proton number, but different bonding arrangements give different bulk properties. In diamond, every carbon atom forms four covalent bonds to four other carbon atoms, arranged tetrahedrally. A finite lattice model has artificial edges: edge atoms have neighbours omitted.','diamond'),
C('Explain hardness and melting.','Strong covalent bonds link diamond’s atoms into a rigid network in three dimensions. There are no layers that can slide easily, making diamond very hard and useful in cutting tools. Overcoming many strong covalent bonds requires much energy, giving a very high melting point. Hardness and melting point are different properties, even though both are explained using structure and bonding.','diamond'),
C('Electrons are present, but not free to conduct.','Carbon has four outer electrons. In diamond these are involved in covalent bonds; there are no delocalised electrons or mobile ions to carry an electrical current through the structure. Diamond therefore does not conduct electricity. “It has no electrons” is incorrect. A ball-and-stick model shows connections, not literal rods or accurate atom sizes.','diamond')],practice:[
N('p-diamond1','How many covalent neighbours does an internal carbon have in diamond?',4,'Each carbon forms four covalent bonds in a tetrahedral arrangement.','diamond-bonds','neighbours'),
Q('p-diamond2','Why can diamond be used on cutting tools?',['It is very hard because of its rigid covalent network','Its layers slide easily','It is soft because it contains small molecules'],0,'Strong covalent connections throughout the 3D network resist deformation.','diamond-properties'),
Q('p-diamond3','Why does diamond not conduct electricity?',['It has no electrons anywhere','Its electrons are delocalised','It lacks mobile charged particles'],2,'Bonding electrons are present but are not delocalised charge carriers.','carbon-conduction')],check:[
N('c-diamond1','How many other carbon atoms bond to each carbon in bulk diamond?',4,'Four covalent neighbours give a tetrahedral giant structure.','diamond-bonds','carbon neighbours'),
Q('c-diamond2','Which explains diamond’s high melting point?',['Many strong covalent bonds need energy to overcome','Only weak intermolecular forces act between diamond molecules','Its atoms individually have high melting points'],0,'Diamond is a network; many strong covalent bonds must be overcome.','diamond-properties'),
Q('c-diamond3','Which statement about diamond’s electrons is correct?',['Outer electrons are involved in bonds, with no delocalised carriers','Diamond contains no electrons','All electrons can flow freely through the lattice'],0,'The lack of delocalised electrons explains electrical insulation.','carbon-conduction'),
Q('c-diamond4','Why does a finite model show some carbons with fewer than four bonds?',['The sample omits neighbours beyond its edges','Bulk diamond has no consistent bonding','Those carbons must be a different element'],0,'Artificial model boundaries cut off part of the real structure.','carbon-models'),
Q('c-diamond5','Diamond and graphite have different properties because…',['Their carbon atoms have different proton numbers','Their bonding arrangements differ','One contains only oxygen'],1,'Both are carbon allotropes, with different structures.','carbon-allotropes')],skills:['WS1.2','MS5b']},
{id:'science.chemistry.bonding.graphite',title:'Graphite: layers & mobile electrons',short:'Strong sheets, sliding layers',refs:['2.3.2'],minutes:20,widget:'graphite-lab',prerequisites:['science.chemistry.bonding.diamond','science.chemistry.bonding.metallic'],big:'Each graphite carbon forms three covalent bonds in a hexagonal sheet. Weak attractions allow sheets to slide; delocalised electrons allow electrical conduction.',learn:[
C('Count bonds within a layer.','In graphite, each carbon atom bonds covalently to three other carbon atoms in a sheet of hexagonal rings. Strong bonds extend through each sheet. There are no covalent bonds between the layers. Our sample contains three sheets; a real piece has many more. Edge atoms appear under-bonded because the rest of the sheet is omitted.','graphite'),
C('Separate sliding from melting.','Weak attractions between layers allow them to slide over each other, explaining graphite’s softness and usefulness as a lubricant or pencil material. Sliding does not require breaking all the strong covalent bonds within the sheets. Graphite still has a very high melting point because overcoming the strong covalent network needs much energy. Weak interlayer forces do not make every property weak.','graphite'),
C('Find the fourth electron.','Each carbon contributes three outer electrons to covalent bonding, leaving one delocalised electron per carbon. These electrons can move through the sheets and carry charge, so graphite conducts electricity. This resembles metallic conduction through delocalised electrons, although graphite is a non-metal. The model does not show electron trajectories or measure current.','graphite')],practice:[
N('p-graphite1','How many covalent neighbours does each internal graphite carbon have?',3,'Three covalent bonds form the hexagonal sheet.','graphite-bonds','neighbours'),
Q('p-graphite2','Which interactions are overcome as graphite layers slide?',['Weak attractions between layers','Every covalent bond within each sheet','Bonds inside every carbon nucleus'],0,'Layers can slide while their internal covalent bonds remain intact.','graphite-layers'),
Q('p-graphite3','What carries electrical charge in graphite?',['Moving protons','Delocalised electrons','Neutral layers alone'],1,'One electron per carbon is delocalised and can carry charge through the sheet.','carbon-conduction')],check:[
N('c-graphite1','How many delocalised electrons are contributed by 12 internal carbon atoms in graphite?',12,'One electron per carbon gives twelve delocalised electrons.','carbon-conduction','electrons'),
Q('c-graphite2','Why is graphite suitable as a lubricant?',['Layers slide over each other because attractions between them are weak','Every covalent bond is weak','Its carbon atoms turn into liquid atoms'],0,'Weak interlayer attraction allows sliding.','graphite-layers'),
Q('c-graphite3','Why does graphite have a very high melting point?',['Strong covalent bonds within its sheets need much energy to overcome','It contains only weak forces','Electrons have their own high melting point'],0,'Strong within-sheet bonding remains despite weak forces between layers.','graphite-properties'),
Q('c-graphite4','Which comparison is correct?',['Diamond has four neighbours per carbon; graphite has three','Diamond and graphite both have one neighbour per carbon','Graphite has four and diamond has three'],0,'The bonding arrangements differ between the two allotropes.','graphite-bonds'),
Q('c-graphite5','Why can graphite conduct while diamond cannot?',['Graphite has delocalised electrons; diamond does not','Graphite has protons; diamond does not','Graphite is an ionic metal'],0,'Mobile delocalised electrons provide charge carriers.','carbon-conduction')],skills:['WS1.2','MS5b']},
{id:'science.chemistry.bonding.graphene-fullerenes',title:'Graphene, fullerenes & nanotubes',short:'Sheets, cages and cylinders',refs:['2.3.3'],minutes:25,widget:'carbon-use-lab',prerequisites:['science.chemistry.bonding.graphite'],big:'Carbon can form a one-atom-thick sheet, a hollow cage or a long cylinder. Use structure and supplied property evidence to justify applications.',learn:[
C('One sheet: graphene.','Graphene is a single layer of graphite, one atom thick, with carbon atoms joined in a hexagonal network. Strong covalent bonding makes it strong, while delocalised electrons allow electrical conduction. These properties make it useful in electronic materials and composites. A small flat model represents only a fragment of an extended sheet, not a separate six-atom molecule.','graphene'),
C('A hollow cage: fullerenes.','Fullerenes are carbon molecules with hollow shapes, based on rings. Their structures can contain five- or seven-membered rings as well as hexagons. Buckminsterfullerene, C₆₀, is a spherical cage with sixty carbon atoms. Its pentagons help the network curve and close. The cage model here has sixty vertices and three bonds at each atom; sticks and distances are symbolic.','fullerene'),
C('A long hollow cylinder: nanotubes.','Carbon nanotubes are cylindrical fullerenes with a very high length-to-diameter ratio. Strong bonding and electrical properties make them useful in composite materials, electronics and nanotechnology. Our tube view is a shape sketch, not an accurate atomic lattice. Actual nanotube properties depend on their detailed structure; do not assume every nanotube conducts in the same way.','nanotube'),
C('Justify a use from evidence.','A strong conducting sheet can suit an electronic component. Strong, low-mass nanotubes can reinforce a composite. Hollow fullerene cages have been investigated as carriers for molecules in drug delivery; whether a specific design works depends on evidence about release, targeting and toxicity. A possible use is not proof that every application is effective or safe. Match the required property to the material, then state a limitation.','fullerene')],practice:[
Q('p-newcarbon1','Which is a single layer of graphite?',['Graphene','Diamond','A C₆₀ cage'],0,'Graphene is a one-atom-thick hexagonal sheet.','graphene'),
Q('p-newcarbon2','Which rings occur in the C₆₀ cage?',['Only hexagons','Pentagons and hexagons','Only triangles'],1,'C₆₀ contains twelve pentagons and twenty hexagons.','fullerenes'),
Q('p-newcarbon3','Which evidence supports using nanotubes to reinforce a lightweight composite?',['High strength and low mass','Only their colour','They must be soft liquids'],0,'A reinforcing material needs strength without adding excessive mass.','carbon-uses')],check:[
Q('c-newcarbon1','A one-atom-thick conducting carbon sheet is…',['Graphene','A diamond crystal','A spherical fullerene cage'],0,'Graphene has a single hexagonal layer and delocalised electrons.','graphene'),
N('c-newcarbon2','How many carbon atoms are in one C₆₀ molecule?',60,'The subscript sixty counts carbon atoms in one molecule.','fullerenes','carbon atoms'),
Q('c-newcarbon3','Which structure identifies a carbon nanotube?',['A long hollow carbon cylinder','A solid copper rod','A three-dimensional diamond network'],0,'Nanotubes are cylindrical fullerenes with high length-to-diameter ratios.','nanotubes'),
Q('c-newcarbon4','A device needs a very thin conducting sheet. Which property supports choosing graphene?',['Delocalised electrons in a one-layer carbon network','No mobile electrons in a thick rigid crystal','Weak bonds inside separate small molecules'],0,'Its sheet structure and mobile electrons support the stated requirement.','carbon-uses'),
Q('c-newcarbon5','A hollow cage is proposed for drug delivery. What is a sound evaluation?',['Its shape may help carry molecules, but release and toxicity need evidence','The shape proves all such treatments are safe','It must work because all carbon is identical'],0,'A structural opportunity must be tested for the particular application.','carbon-uses')],skills:['WS1.2','WS1.4','MS5b']}
];
